// ---- HALL ART DEPARTMENT -----------------------------------------------------
// "The lease said AS-IS. We said OTHERWISE." — THE GRAND REOPENING
//
// Every surface in the Nugget Arcade hall — and the street outside, and the
// regulars who loiter on it — was modeled and lit in Blender (blender/
// hallrig.py), rendered at 4x, graded to the exact procedural palette the
// hall has always worn, and packed into this one sheet. The painters in
// js/arcade-art.js blit their regions from it and keep their procedural
// rigs as fallback: if this sheet ever fails to decode, the hall degrades
// to the old paint, never to black. Text stays runtime-crisp on top.
//
// Regeneration: blender/hallrig.py (render_all) -> blender/pack_hall.py.
// Regions are [x, y, w, h] in sheet pixels. Loads before js/arcade-art.js.

const HALL_ART_REGIONS = {"across": [518, 710, 512, 192], "bezel": [1032, 710, 256, 192], "brick": [1106, 2, 256, 256], "cabFront": [1364, 2, 256, 256], "carpet": [2, 2, 448, 448], "ceiling": [1622, 2, 256, 256], "change": [1880, 2, 128, 256], "cupGravy": [906, 1586, 192, 96], "dark": [1484, 710, 128, 128], "door": [452, 2, 192, 448], "henWhite": [1198, 1586, 64, 64], "highscores": [2, 936, 512, 128], "hoodCloth": [1264, 1586, 64, 64], "marq_blaster": [516, 936, 512, 128], "marq_brawl": [1030, 936, 512, 128], "marq_catch": [2, 1066, 512, 128], "marq_dunk": [516, 1066, 512, 128], "marq_flappy": [1030, 1066, 512, 128], "marq_kart": [2, 1196, 512, 128], "marq_knight": [516, 1196, 512, 128], "marq_ranch": [1030, 1196, 512, 128], "marq_run": [2, 1326, 512, 128], "marq_sim": [516, 1326, 512, 128], "metal": [1030, 1326, 128, 128], "nugSkin": [1100, 1586, 96, 96], "open": [1160, 1326, 256, 128], "panel_blaster": [520, 1456, 224, 112], "panel_brawl": [746, 1456, 224, 112], "panel_catch": [972, 1456, 224, 112], "panel_dunk": [1198, 1456, 224, 112], "panel_flappy": [1424, 1456, 224, 112], "panel_kart": [1650, 1456, 224, 112], "panel_knight": [2, 1586, 224, 112], "panel_ranch": [228, 1586, 224, 112], "panel_run": [454, 1586, 224, 112], "panel_sim": [680, 1586, 224, 112], "phrase": [1418, 1326, 512, 128], "pickle": [1330, 1586, 64, 64], "pierWood": [2, 1456, 128, 128], "road": [1290, 710, 192, 192], "shopGarage": [1544, 452, 256, 224], "shopLaundro": [2, 710, 256, 224], "shopNoodle": [260, 710, 256, 224], "sideBase": [904, 2, 200, 300], "sidewalk": [2, 452, 256, 256], "sign": [260, 452, 1024, 256], "vending": [646, 2, 256, 384], "wainscot": [132, 1456, 256, 128], "wall": [1286, 452, 256, 256], "water": [390, 1456, 128, 128]};

const HallArt = (() => {
  const img = new Image();
  let ok = false;
  img.onload = () => { ok = true; if (api.onReady) api.onReady(); };
  img.onerror = () => { ok = false; };
  img.src = 'data:image/jpeg;base64,';

  // Fill the current painter's region (painters run inside a translate+clip,
  // so the destination is always 0,0..w,h). Returns false -> caller paints
  // its procedural fallback.
  function blit(g, name, w, h) {
    const r = HALL_ART_REGIONS[name];
    if (!api.on() || !r) return false;
    g.drawImage(img, r[0], r[1], r[2], r[3], 0, 0, w, h);
    return true;
  }

  const api = { on: () => ok, blit, img, R: HALL_ART_REGIONS, onReady: null };
  return api;
})();
